class LmdbLegacyAliasWitnessRegressionTest {

	private static final int ROWS = 1_100;
	private static final byte[] EXTERNAL_KEY = "test.alias-witness.external-writer".getBytes(StandardCharsets.UTF_8);

	@TempDir(cleanup = CleanupMode.NEVER)
	Path fixture;

	@Test
	void unchangedCleanLegacyGenerationHasBoundedForegroundReadWork() throws Exception {
		Path store = fixture.resolve("unchanged");
		boolean trustedBefore = prepareLegacyStore(store);
		StartupResult result = openAndMeasure(store);
		assertEquals(trustedBefore, result.trusted(), "a scan witness must not grant reference-count authority");
		assertEquals(0L, result.drops(), "foreground startup must not drop a native tree");
		assertTrue(result.reads() <= 1_000,
				() -> "an unchanged, cleanly closed legacy dictionary should not be rescanned: " + result.operations());
	}

	@Test
	void unownedDictionaryWriteForcesRevalidation() throws Exception {
		Path store = fixture.resolve("external-writer");
		boolean trustedBefore = prepareLegacyStore(store);
		long closedId = LmdbCompatibilityFixtures.nativeTransactionId(store);
		assertNull(LmdbCompatibilityFixtures.nativeGet(store, "gc_meta", EXTERNAL_KEY));
		LmdbCompatibilityFixtures.nativePut(store, "gc_meta", EXTERNAL_KEY, new byte[] { 1 });
		assertTrue(LmdbCompatibilityFixtures.nativeTransactionId(store) > closedId,
				"the unowned native writer must advance the dictionary transaction");
		StartupResult result = openAndMeasure(store);
		assertEquals(trustedBefore, result.trusted(), "revalidation must not grant reference-count authority");
		assertEquals(0L, result.drops());
		assertTrue(result.reads() > 1_000,
				() -> "an unowned dictionary generation requires synchronous validation: " + result.operations());
	}

	@Test
	void swappedPropertiesCannotAuthenticateADifferentDictionaryAtTheSameNativeId() throws Exception {
		Path original = fixture.resolve("original");
		boolean trustedBefore = prepareLegacyStore(original);
		Path certified = fixture.resolve("certified");
		Path changed = fixture.resolve("changed");
		copyStore(original, certified);
		copyStore(original, changed);
		openAndMeasure(certified);
		long targetId = LmdbCompatibilityFixtures.nativeTransactionId(certified);
		long changedId = LmdbCompatibilityFixtures.nativeTransactionId(changed);
		assertTrue(targetId > changedId,
				() -> "the separately closed owner must create a later native generation: " + targetId + "/" + changedId);
		assertNull(LmdbCompatibilityFixtures.nativeGet(changed, "gc_meta", EXTERNAL_KEY));
		for (long step = changedId; step < targetId; step++) {
			LmdbCompatibilityFixtures.nativePut(changed, "gc_meta", EXTERNAL_KEY,
					Long.toString(step).getBytes(StandardCharsets.UTF_8));
		}
		assertEquals(targetId, LmdbCompatibilityFixtures.nativeTransactionId(changed),
				"the different native dictionary must have the same numeric transaction ID");
		assertEquals(nativeTripleTransactionId(certified), nativeTripleTransactionId(changed),
				"a sidecar verifier cannot distinguish the two fixtures by triple transaction ID either");
		Files.copy(changed.resolve("store.properties"), fixture.resolve("changed-original.properties"));
		Files.copy(certified.resolve("store.properties"), fixture.resolve("certified.properties"));
		Files.copy(certified.resolve("store.properties"), changed.resolve("store.properties"),
				StandardCopyOption.REPLACE_EXISTING);
		StartupResult result = openAndMeasure(changed);
		assertEquals(trustedBefore, result.trusted());
		assertEquals(0L, result.drops());
		assertTrue(result.reads() > 1_000,
				() -> "a copied sidecar cannot certify another native dictionary: " + result.operations());
	}

	private static boolean prepareLegacyStore(Path directory) throws Exception {
		LmdbCompatibilityFixtures.extract("v2-610-default.zip", directory);
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var vf = SimpleValueFactory.getInstance();
				connection.begin();
				for (int i = 0; i < ROWS; i++) {
					connection.add(vf.createIRI("urn:alias-witness:subject:" + i),
							vf.createIRI("urn:alias-witness:predicate"), vf.createLiteral("alias witness payload " + i));
				}
				connection.commit();
			}
			return ((ValueStore) store.getValueFactory()).hasTrustedReferenceCounts();
		} finally {
			repository.shutDown();
		}
	}

	private static StartupResult openAndMeasure(Path directory) throws Exception {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		SailRepository repository = new SailRepository(store);
		try {
			long reads;
			long drops;
			Map<String, Long> operations;
			try (var counter = new LmdbStartupReadCounter()) {
				repository.init();
				reads = counter.total();
				drops = counter.treeDrops();
				operations = counter.operations();
			}
			try (var connection = repository.getConnection()) {
				var vf = SimpleValueFactory.getInstance();
				assertTrue(connection.hasStatement(vf.createIRI("urn:alias-witness:subject:0"),
						vf.createIRI("urn:alias-witness:predicate"), vf.createLiteral("alias witness payload 0"), false));
				assertTrue(connection.hasStatement(vf.createIRI("urn:alias-witness:subject:" + (ROWS - 1)),
						vf.createIRI("urn:alias-witness:predicate"),
						vf.createLiteral("alias witness payload " + (ROWS - 1)), false));
				try (var statements = connection.getStatements(null, vf.createIRI("urn:alias-witness:predicate"), null)) {
					long count = 0;
					while (statements.hasNext()) {
						statements.next();
						count++;
					}
					assertEquals(ROWS, count, "every fixture statement must remain readable exactly once");
				}
			}
			return new StartupResult(reads, drops, ((ValueStore) store.getValueFactory()).hasTrustedReferenceCounts(),
					operations);
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig().setInlineLiterals(false).setPredicateGuaranteeIndexEnabled(false)
				.setForceSync(true).setValueDBSize(64L * 1024 * 1024).setTripleDBSize(64L * 1024 * 1024);
	}

	private static long nativeTripleTransactionId(Path store) throws IOException {
		long environment = NULL;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_maxdbs(environment, 128));
			E(mdb_env_open(environment, store.resolve("triples").toString(), MDB_NOTLS | MDB_RDONLY, 0664));
			return LmdbUtil.readTransaction(environment, (inner, txn) -> mdb_txn_id(txn));
		} finally {
			if (environment != NULL) {
				mdb_env_close(environment);
			}
		}
	}

	private static void copyStore(Path from, Path to) throws IOException {
		try (Stream<Path> paths = Files.walk(from)) {
			for (Path source : paths.toList()) {
				Path relative = from.relativize(source);
				if (source.getFileName().toString().equals("lock.mdb")) {
					continue;
				}
				Path target = to.resolve(relative);
				if (Files.isDirectory(source)) {
					Files.createDirectories(target);
				} else {
					Files.copy(source, target);
				}
			}
		}
	}

	private record StartupResult(long reads, long drops, boolean trusted, Map<String, Long> operations) {
	}
}
